var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

var baseDir = Path.Combine(Directory.GetCurrentDirectory(), "data");

app.MapGet("/files", (string name) =>
{
    var fullBase = Path.GetFullPath(baseDir);
    var path = Path.GetFullPath(Path.Combine(fullBase, name));
    if (!path.StartsWith(fullBase + Path.DirectorySeparatorChar, StringComparison.Ordinal))
    {
        return Results.BadRequest("invalid path");
    }
    if (!File.Exists(path)) return Results.NotFound();
    return Results.Text(File.ReadAllText(path));
});

app.Run("http://0.0.0.0:8056");
